function ygo_normalize_status_key(string $status): string
{
    $status = iconv('UTF-8', 'ASCII//TRANSLIT//IGNORE', $status) ?: $status;
    $status = strtolower(trim($status));
    $status = preg_replace('/[^a-z0-9]+/', '_', $status) ?: '';
    return trim($status, '_');
}

